// One built string per icon, kept forever: the tray, the badge list and the challenge list
// all re-render on every open, and the markup for a given name never changes.
const cache = new Map();

/**
 * The <svg> markup for an icon name, ready to drop into innerHTML.
 *
 * Everything paints with currentColor, so a selected tile turning white, a locked tile going
 * dim and a gold toast all come free from the colour the surrounding CSS already sets. Size
 * comes from font-size on the .ic span, because the whole bar is already sized that way.
 */
export function icon(name) {
  let s = cache.get(name);
  if (s !== undefined) return s;
  const d = RAW[name];
  // A missing name draws nothing rather than throwing: a typo in a badge should not take
  // the panel down with it.
  s = !d ? '' : '<svg class="' + (d[1] ? 's' : 'f') + '" viewBox="0 0 ' + d[0] + ' ' + d[0] +
    '" aria-hidden="true"' + (d[1]
      ? ' fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'
      : ' fill="currentColor">') + d[2] + '</svg>';
  cache.set(name, s);
  return s;
}

/** Fill in every element in the document that names an icon, e.g. the fixed chrome. */
export function paintIcons(root) {
  for (const e of (root || document).querySelectorAll('[data-icon]')) {
    e.innerHTML = icon(e.dataset.icon);
  }
}
